import ast,base64,sys,json,types,pathlib
source=base64.b64decode('').decode()
(budget_root/'start_budget_publisher_runtime.py').write_text(source)
tree=ast.parse(source)
defs=[n for n in ast.walk(tree) if isinstance(n,ast.FunctionDef) and n.name=='_budget_publish_loop']
assert len(defs)==1
exec(compile(ast.Module(body=defs,type_ignores=[]),'<budget-publisher-snapshot-fix>','exec'),globals())
patched=[]
for frame in sys._current_frames().values():
 while frame:
  if frame.f_code.co_name=='_budget_publish_loop':
   fn=frame.f_locals.get('publish_file')
   if fn:
    free=fn.__code__.co_freevars
    store=frame.f_locals.get('store');state=frame.f_locals.get('state');status_path=frame.f_locals.get('status_path')
    def make_snapshot_publisher(store,state,status_path):
     def publish_file(name,path,immutable=False):
      p=pathlib.Path(path)
      if not p.is_file():return None
      snapshot=store.work/('upload_snapshot_'+name)
      shutil.copyfile(p,snapshot);digest=_pub_sha(snapshot);prior=state['artifacts'].get(name)
      if prior and prior.get('sha256')==digest and prior.get('fresh_raw_readback_verified') is True:return prior
      proof=store.put(name,snapshot)
      if proof.get('sha256')!=digest or proof.get('bytes')!=snapshot.stat().st_size or proof.get('fresh_raw_readback_verified') is not True:raise ValueError('Snapshot readback mismatch '+name)
      state['artifacts'][name]=dict(proof,local_sha256=digest,published_utc=datetime.now(timezone.utc).isoformat())
      _pub_atomic_json(status_path,state);return state['artifacts'][name]
     return publish_file
    replacement=make_snapshot_publisher(store,state,status_path)
    assert replacement.__code__.co_freevars==free
    fn.__code__=replacement.__code__;patched.append(list(free))
  frame=frame.f_back
print(json.dumps({'state':'PUBLISH_MUTABLE_FILES_FROM_IMMUTABLE_UPLOAD_SNAPSHOTS','patched_live_publishers':len(patched),'current_and_future_retries_fixed':True,'training_config_changed':False,'checkpoint_corruption_detected':False,'failure_was_mutable_progress_race':True}))
